const D = { density:.5, scale:1, energy:.6, speed:1, hue:210, x:.5, y:.5, style:'kinetic', seed:0, act:'assemble', word:'LIVE' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const TAU=6.28318530718, u=Math.min(width,height);
const fr = i => { const q=Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q-Math.floor(q); };
const style=P.style, H=((P.hue%360)+360)%360;
let word=((''+P.word).toUpperCase()).slice(0,16); if(!/[^ ]/.test(word)) word='LIVE';
const paper = (style==='ink'||style==='halftone');
if (S.lastBeat==null || K.beat<S.lastBeat) S.lastBeat=K.beat; S.lastBeat=K.beat;

// ---- background cache (owns the frame) ----
const bgKey = width+'x'+height+'|'+style+'|'+P.seed+'|'+(H|0);
if (!S.bg || S.bgKey!==bgKey){
  const g = S.bg || (S.bg = createGraphics(width,height));
  g.pixelDensity(1); g.colorMode(HSB,360,100,100,100); g.clear();
  if (paper){
    g.background((H+30)%360, 8, 84);
    g.noStroke();
    for (let i=0;i<1600;i++){ const x=fr(i*2)*width, y=fr(i*2+1)*height; g.fill((H+20)%360, 6, 74+fr(i*3)*12, 12); g.rect(x,y,1.6,1.6); }
    for (let r=0;r<6;r++){ g.noFill(); g.stroke(30,10,55,4); g.strokeWeight(u*0.02*(6-r)); g.rect(0,0,width,height); }
  } else {
    g.background((H+200)%360, 42, 6);
    g.noStroke();
    for (let r=12;r>0;r--){ g.fill((H+180)%360, 45, 5+r*0.55, 5); g.ellipse(width/2,height/2, u*0.16*r, u*0.16*r); }
    for (let i=0;i<900;i++){ const x=fr(i*5)*width, y=fr(i*5+2)*height; g.fill(0,0,92,fr(i*7)*9); g.rect(x,y,1,1); }
  }
  S.bgKey=bgKey;
}
image(S.bg,0,0);

// ---- layout / homes ----
textStyle(BOLD); textAlign(CENTER,CENTER);
const ts=u*0.15*P.scale; textSize(ts);
const gap=ts*0.05;
let total=0;
for (let i=0;i<word.length;i++){ const c=word[i]; total += ((c===' ')?ts*0.5:textWidth(c)) + gap; }
total-=gap;
let cx=P.x*width - total/2;
const homeX=[], homeC=[];
for (let i=0;i<word.length;i++){ const c=word[i]; const w=(c===' ')?ts*0.5:textWidth(c); if(c!==' '){ homeX.push(cx+w/2); homeC.push(c);} cx += w+gap; }
const nSlots=Math.max(1,homeC.length);
const homeY=P.y*height;

// ---- particle rebuild ----
const extras=Math.round(P.density*64);
const N=Math.min(90, nSlots+extras);
const pKey=nSlots+'|'+N+'|'+P.seed+'|'+word;
if (!S.parts || S.pKey!==pKey){
  S.parts=[];
  for (let i=0;i<N;i++){
    const slot = i<nSlots? i : -1;
    let c = slot>=0? homeC[slot] : word[Math.floor(fr(i*9+1)*word.length)];
    if (c===' ') c=homeC[i%nSlots];
    S.parts.push({ id:i, slot, c,
      fx:0.3+fr(i*3)*0.9, fy:0.3+fr(i*4+2)*0.9,
      ph:fr(i*5)*TAU, ph2:fr(i*6+1)*TAU,
      ax:0.30+fr(i*7)*0.17, ay:0.28+fr(i*8+3)*0.17,
      px:P.x*width, py:P.y*height, ppx:P.x*width, ppy:P.y*height });
  }
  S.pKey=pKey;
}

// ---- assemble dramaturgy ----
const sp=P.speed, act=P.act;
const breath=0.5+0.5*Math.sin(K.t*0.12*sp + 1.3);
const twProg=(K.beat*sp)%(nSlots+3);
function slotAsm(p){
  if (p.slot<0) return 0;
  if (act==='swarm') return 0.06*breath;
  if (act==='typewriter') return constrain(twProg - p.slot, 0, 1);
  return constrain(0.45*breath + 0.55*constrain((K.intensity-0.25)/0.6,0,1), 0, 1);
}

// ---- per-glyph render by style ----
function drawG(c,x,y,vx,vy,lit,id,gs){
  if (style==='wireframe'){
    noFill(); stroke(H,55,95, 42+lit*48); strokeWeight(Math.max(1,gs*0.018));
    text(c,x,y); noStroke(); return;
  }
  if (style==='glitch'){
    blendMode(ADD); noStroke();
    const o=gs*0.06*(1+(A.treble||0)*3);
    const sl=(fr(id+Math.floor(K.t*20))<0.12)? gs*0.28 : 0;
    fill(0,80,100,58); text(c,x-o,y);
    fill(150,80,100,58); text(c,x+o+sl,y);
    fill(225,80,100,58); text(c,x,y-o);
    blendMode(BLEND); return;
  }
  if (style==='thermal'){
    const s=constrain((Math.abs(vx)+Math.abs(vy))/(gs*0.6),0,1);
    const hh=(240 - s*240 + 360)%360;
    const bb=52 + s*46;
    const ss=(s>0.9)? Math.max(0,(1-(s-0.9)*9))*100 : 100;
    noStroke(); fill(hh, ss, bb, 58+lit*38); text(c,x,y);
    if (s>0.62){ fill(58,18,100,55*lit); text(c,x,y); }
    return;
  }
  if (style==='ink'){
    noStroke(); const ink=(H+15)%360;
    for (let q=0;q<3;q++){ const ox=(fr(id*7+q)-0.5)*gs*0.05, oy=(fr(id*7+q+9)-0.5)*gs*0.05;
      fill(ink, 32, 12+q*4, 24 - q*5 + lit*24); text(c,x+ox,y+oy); }
    fill(ink,42,8, 28+lit*28); text(c,x+gs*0.01,y);
    return;
  }
  if (style==='halftone'){
    blendMode(MULTIPLY); noStroke();
    const o=gs*0.03*(1+(A.treble||0)*2);
    fill(190,80,90,72); text(c,x-o,y-o*0.5);
    fill(320,80,90,72); text(c,x+o,y);
    fill(55,85,95,72);  text(c,x,y+o);
    blendMode(BLEND); return;
  }
  // kinetic (default): clean mass + additive motion streaks
  blendMode(ADD); noStroke();
  for (let q=1;q<=2;q++){ const f=q*0.55; fill(H,55,100, 9+lit*11); text(c,x-vx*f,y-vy*f); }
  blendMode(BLEND);
  fill(H, 28+lit*16, 100, 68+lit*30); text(c,x,y);
}

// ---- update + draw ----
const eng=P.energy;
for (let k=0;k<S.parts.length;k++){
  const p=S.parts[k];
  const a=slotAsm(p);
  const wx=(0.5+p.ax*Math.sin(K.t*p.fx*0.33 + p.ph))*width;
  const wy=(0.5+p.ay*Math.cos(K.t*p.fy*0.29 + p.ph2))*height;
  const hx=p.slot>=0?homeX[p.slot]:wx;
  const hy=p.slot>=0?homeY:wy;
  const jitS=ts*(0.015+0.05*(1-a))*(0.6+eng);
  const jx=Math.sin(K.t*6*p.fx+p.ph)*jitS + (A.treble||0)*ts*0.12*(fr(p.id*3+Math.floor(K.t*24))-0.5)*2;
  const jy=Math.cos(K.t*5*p.fy+p.ph2)*jitS + (1-a)*K.pulse*ts*0.2*Math.sin(p.ph*2);
  p.ppx=p.px; p.ppy=p.py;
  p.px=lerp(wx,hx,a)+jx;
  p.py=lerp(wy,hy,a)+jy;
  const vx=p.px-p.ppx, vy=p.py-p.ppy;
  const gs=ts*(p.slot>=0?1:(0.5+0.4*fr(p.id)));
  textSize(gs);
  const lit=p.slot>=0?(0.5+0.5*a):0.42;
  drawG(p.c, p.px, p.py, vx, vy, lit, p.id, gs);
}
textSize(ts);
blendMode(BLEND); drawingContext.shadowBlur=0;
